mapper.select:
select id, user_id, title, created_at, updated_at, last_message_at
from ai_chat_session
where id = #{id}
  and user_id = #{userId}
  and deleted = 0

mapper.update:
update ai_chat_session
set updated_at = now(),
    last_message_at = #{lastMessageAt}
where id = #{id}
  and deleted = 0

update ai_chat_session
set title = #{title},
    updated_at = now()
where id = #{id}
  and user_id = #{userId}
  and deleted = 0

update ai_chat_session
set deleted = 1,
    updated_at = now()
where id = #{id}
  and user_id = #{userId}
  and deleted = 0
